def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find rectangular frames of 2s whose borders are complete. For frames
    # containing an interior 2 marker, turn other interior cells into 8.
    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                for right in range(left + 2, w):
                    if not (all(grid[top][c] == 2 for c in range(left, right + 1)) and
                            all(grid[bottom][c] == 2 for c in range(left, right + 1)) and
                            all(grid[r][left] == 2 for r in range(top, bottom + 1)) and
                            all(grid[r][right] == 2 for r in range(top, bottom + 1))):
                        continue
                    if any(grid[r][c] == 2 for r in range(top + 1, bottom) for c in range(left + 1, right)):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                if grid[r][c] == 0:
                                    out[r][c] = 8
    return out

